  "runner.mjs":
    '#!/usr/bin/env node\n// R3 node-ts-v1 受信 runner（v4：测试子进程输出改流式转发 + 尾部 2 MiB 供 TAP 门）\n// 固定命令：typecheck | test | selfcheck-gate\n// 设计口径（design D2）：命令仅枚举、argv 由本文件固定、可信测试只来自 /opt/r3/tests；\n// test 先编译再执行可信 Node 测试；零测试不得通过。\n// v4 修复（6.2）：v3 用 spawnSync 默认 1 MiB maxBuffer，测试输出超过 1 MiB 会 ENOBUFS\n// 并被误判为断言失败；改为流式转发，外层执行器负责有界保留/总观测击杀（P13）。\nimport { spawn, spawnSync } from "node:child_process";\nimport { copyFileSync, readdirSync } from "node:fs";\nimport { constants } from "node:os";\nimport { join } from "node:path";\n\nconst TEST_DIR = "/opt/r3/tests";\nconst TSC = "/opt/r3/node_modules/.bin/tsc";\n// 预期测试数（design D2「检查预期测试数和报告」）：与 /opt/r3/tests 同镜像冻结。\n// node 22.23 会把零用例文件计作 1 个通过的「模块加载」测试并 exit 0，故必须精确匹配而非 >0。\nconst EXPECTED_TESTS = 2;\n// TAP 摘要在输出尾部；只保留尾部 2 MiB 做门判定，不在内存里留全量输出。\nconst TAIL_LIMIT = 2 * 1024 * 1024;\n\nfunction fail(code, msg) {\n  console.error(`R3_RUNNER_FAIL(${code}): ${msg}`);\n  process.exit(code);\n}\n\nexport function checkTestGate(files, tapText, expected = EXPECTED_TESTS) {\n  if (!Array.isArray(files) || files.length === 0) {\n    return { ok: false, reason: "trusted test dir empty" };\n  }\n  const m = [...tapText.matchAll(/^# tests (\\d+)$/gm)].pop();\n  const total = m ? Number(m[1]) : -1;\n  if (total !== expected) {\n    return { ok: false, reason: `reported tests=${total} != expected ${expected}` };\n  }\n  return { ok: true, reason: `tests=${total}` };\n}\n\nfunction compile(emit) {\n  // 模板 tsconfig/package 从固定环境落位到 /work（同字节），再由 tsc 编译\n  copyFileSync("/opt/r3/tsconfig.json", "/work/tsconfig.json");\n  copyFileSync("/opt/r3/package.tmpl.json", "/work/package.json");\n  const args = emit ? ["-p", "/work/tsconfig.json"] : ["--noEmit", "-p", "/work/tsconfig.json"];\n  const r = spawnSync(TSC, args, { stdio: "inherit" });\n  if (r.error) fail(3, "tsc spawn failed: " + r.error.message);\n  if (r.status !== 0) fail(1, "typecheck failed (exit " + r.status + ")");\n}\n\n// tsc 输出很小，同步即可；可信测试输出可能很大 ⇒ 必须流式，否则会被缓冲上限截断。\nfunction runTests(files) {\n  return new Promise((resolve) => {\n    const child = spawn(\n      process.execPath,\n      ["--test", "--test-reporter=tap", ...files.map((f) => join(TEST_DIR, f))],\n      { cwd: "/work", stdio: ["ignore", "pipe", "pipe"] },\n    );\n    let tail = "";\n    const forward = (chunk, target) => {\n      target.write(chunk);\n      tail = (tail + chunk.toString()).slice(-TAIL_LIMIT);\n    };\n    child.stdout.on("data", (chunk) => forward(chunk, process.stdout));\n    child.stderr.on("data", (chunk) => forward(chunk, process.stderr));\n    child.on("error", (error) => resolve({ error }));\n    child.on("close", (code, signal) => resolve({ code, signal, tail }));\n  });\n}\n\nconst cmd = process.argv[2];\nif (cmd === "typecheck") {\n  compile(false);\n  process.exit(0);\n}\nif (cmd === "test") {\n  compile(true);\n  const files = readdirSync(TEST_DIR).filter((f) => f.endsWith(".test.mjs"));\n  if (files.length === 0) fail(2, "no trusted test files");\n  const result = await runTests(files);\n  if (result.error) fail(3, "node --test spawn failed: " + result.error.message);\n  // 被信号终止 = 进程异常（OOM/SIGKILL 等），按 128+n 退出，供外层分类为 process_failed；\n  // 不能先跑 TAP 门（输出很可能不完整，会把基础设施问题伪装成断言失败）。\n  if (result.signal !== null && result.signal !== undefined) {\n    const number = constants.signals[result.signal] ?? 0;\n    process.exit(number === 0 ? 3 : 128 + number);\n  }\n  // node --test 会把被信号杀死的测试文件标成 TAP 失败而自身 exit 1（OOM/SIGSEGV 等）；\n  // 从尾部 TAP 提取 signal，按 128+n 退出，避免基础设施故障被记成断言失败（P20）。\n  const killed = /signal: \'(SIG[A-Z]+)\'/.exec(result.tail);\n  if (killed !== null) {\n    const number = constants.signals[killed[1]] ?? 0;\n    process.exit(number === 0 ? 3 : 128 + number);\n  }\n  const gate = checkTestGate(files, result.tail);\n  if (!gate.ok) fail(2, "test gate: " + gate.reason);\n  process.exit(result.code === null ? 3 : result.code);\n}\nif (cmd === "selfcheck-gate") {\n  const cases = [\n    [[], "", false],\n    [["a.test.mjs"], "# tests 0\\n# pass 0\\n", false],\n    [["a.test.mjs"], "# tests 2\\n# pass 2\\n", true],\n    [["a.test.mjs"], "garbage-no-summary", false],\n    [["a.test.mjs"], "# tests 1\\n# pass 1\\n", false], // 零用例文件的「模块加载伪测试」形态\n    [["a.test.mjs", "b.test.mjs"], "# tests 3\\n# pass 3\\n", false], // 超计数也拒绝\n  ];\n  let bad = 0;\n  for (const [files, tap, expect] of cases) {\n    const g = checkTestGate(files, tap);\n    if (g.ok !== expect) {\n      bad++;\n      console.error(`gate case wrong: files=${JSON.stringify(files)} tap=${JSON.stringify(tap)} => ${g.reason}`);\n    }\n  }\n  console.log(bad === 0 ? "GATE_SELFCHECK_PASS" : `GATE_SELFCHECK_FAIL(${bad})`);\n  process.exit(bad === 0 ? 0 : 2);\n}\nfail(2, "unknown command: " + cmd);\n',
